#!/usr/bin/env python3
"""
Generates the self-hosted "Tech Stack" icon-strip SVGs for the profile
README (assets/tech-stack-light.svg + assets/tech-stack-dark.svg), replacing
the plain-text Languages/Hardware/Software & Tools lines.

Real logos are Simple Icons (CC0, https://simpleicons.org) path data, copied
in below so this script has no network dependency at generation time. A few
more (MATLAB/MathWorks, Onshape, Webots, and Xilinx for FPGA/Vivado) use
their actual official marks too, sourced directly from MathWorks/Wikimedia,
onshape.com and the cyberbotics/webots repo since Simple Icons no longer
carries them. Tools with no available brand mark at all (Verilog, Assembly,
SQL, G-code, SolidWorks) render as generic outline pictograms instead, using
Tabler Icons (MIT, https://tabler.io/icons) path data in a neutral accent
color rather than any company's actual logo mark.

Two variants are produced because GitHub's own light/dark README image
switching (the <picture><source media="(prefers-color-scheme: dark)"> trick)
only works across separate image files, not via @media queries inside a
single SVG loaded through <img>.

Run manually whenever the stack list changes:
    python scripts/generate_tech_stack.py
"""

import os

# (title, kind, payload, hex)
#   kind "icon"    -> payload is a Simple Icons <path d="..."> string, filled
#                     solid with hex, the tool's real brand color.
#   kind "outline" -> payload is one or more Tabler Icons <path d="...">
#                     strings (joined), stroked (not filled) with hex, a
#                     neutral accent color picked for this generator, since
#                     there is no official brand mark to color-match.
#   kind "raster"  -> payload is a base64 PNG (the official logo), hex unused.

